diff --git a/runner/logEvents.js b/runner/logEvents.js
new file mode 100644
index 0000000..7268bf4
--- /dev/null
+++ b/runner/logEvents.js
@@ -0,0 +1,264 @@
+import { redactDeepStrings } from "../shared/redactSecrets.js";
+
+/**
+ * MARK: structuredEventSender
+ * @description Batches normalized agent session events for the backend
+ *   `POST /tasks/:id/log-events` endpoint (structured log transport). The
+ *   sender redacts every event before it leaves the Runner (defense in depth
+ *   for locally-read secrets), caps oversized payloads, and degrades to
+ *   legacy text frames: the first failed batch flips the sender to
+ *   text-fallback mode, converts that batch to text, and all later events
+ *   flow through the daemon's `onLog` path instead — so an old backend
+ *   degrades to today's coarse text view instead of losing logs.
+ *
+ *   Pure batching over an injected client: no harness imports, no I/O of its
+ *   own. The daemon owns the `onLog` gating via `isStructured()`.
+ */
+
+/***
+ * MARK: MAX_EVENT_BYTES
+ * @description Per-event JSON cap before transport. Oversized payloads (full
+ *   file contents in a tool result) are truncated field-first, never dropped
+ *   silently without the marker.
+ * @example MAX_EVENT_BYTES => 65536
+ ***/
+export const MAX_EVENT_BYTES = 65536;
+
+/***
+ * MARK: sanitizeStructuredEvent
+ * @description Makes one session event JSON-safe and transport-bounded:
+ *   redacts secrets/PII (position- and shape-aware), drops functions and
+ *   unserializable values via a JSON round-trip, and truncates oversized
+ *   payload fields with a visible marker. Returns null when the event has no
+ *   usable type or still exceeds the cap after truncation.
+ * @example sanitizeStructuredEvent({ type: 'assistant_delta', delta: 'hi' }) => { type: 'assistant_delta', delta: 'hi' }
+ * @param {Object} event - One normalized session event.
+ * @param {number} [maxBytes] - Per-event JSON cap.
+ * @returns {Object|null} The sanitized event, or null to skip it.
+ ***/
+export const sanitizeStructuredEvent = (event, maxBytes = MAX_EVENT_BYTES) => {
+	if (!event || typeof event !== "object" || typeof event.type !== "string") {
+		return null;
+	}
+	const cap = maxBytes > 0 ? maxBytes : MAX_EVENT_BYTES;
+	let redacted;
+	try {
+		redacted = redactDeepStrings(event);
+	} catch {
+		return null;
+	}
+	const sizeOf = (value) => {
+		try {
+			return JSON.stringify(value)?.length ?? Infinity;
+		} catch {
+			return Infinity;
+		}
+	};
+	if (sizeOf(redacted) <= cap) return redacted;
+	// Truncate the large free-text payload fields first, keeping the event
+	// envelope (type, toolName, meta) so the step stays visible.
+	const truncated = { ...redacted };
+	for (const field of ["result", "partialResult", "delta", "content", "text", "output"]) {
+		if (typeof truncated[field] === "string" && truncated[field].length > 1000) {
+			truncated[field] = `${truncated[field].slice(0, 1000)}…[truncated for transport]`;
+		}
+		if (sizeOf(truncated) <= cap) return truncated;
+	}
+	// Object-shaped payloads (e.g. result {content:[{text}]}) carry their
+	// bulk in nested strings: truncate every long string in place (the
+	// redacted clone is ours to mutate) before giving up on the event.
+	const seen = new Set();
+	const truncateDeep = (node) => {
+		if (!node || typeof node !== "object" || seen.has(node)) return;
+		seen.add(node);
+		for (const key of Object.keys(node)) {
+			// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked payload
+			const child = node[key];
+			if (typeof child === "string" && child.length > 1000) {
+				// eslint-disable-next-line security/detect-object-injection -- key comes from Object.keys of the walked payload
+				node[key] = `${child.slice(0, 1000)}…[truncated for transport]`;
+			} else {
+				truncateDeep(child);
+			}
+		}
+	};
+	truncateDeep(truncated);
+	if (sizeOf(truncated) <= cap) return truncated;
+	return null;
+};
+
+/***
+ * MARK: textForStructuredEvent
+ * @description Legacy text derivation for one structured event — the same two
+ *   shapes the pre-structured `onLog` path forwarded
+ *   (`assistant_delta.delta`, `harness_log.text`). Returns null for
+ *   tool/telemetry/permission/plan events, which have no legacy text form.
+ * @example textForStructuredEvent({ type: 'assistant_delta', delta: 'hi' }) => 'hi'
+ * @param {Object} event - One normalized session event.
+ * @returns {string|null} The legacy text, or null when there is none.
+ ***/
+export const textForStructuredEvent = (event) => {
+	if (!event || typeof event !== "object") return null;
+	if (event.type === "assistant_delta" && typeof event.delta === "string") {
+		return event.delta;
+	}
+	if (event.type === "harness_log" && typeof event.text === "string") {
+		return event.text;
+	}
+	return null;
+};
+
+/***
+ * MARK: createStructuredEventSender
+ * @description Buffers sanitized session events and ships them as sequenced
+ *   batches. Flushes on `batchSize`, on `flushMs` of quiet, on explicit
+ *   `flush()`/`close()`, and immediately on run-closing events
+ *   (`run_finished`, `run_error`) so the tail never waits for the timer.
+ *   `flush()`/`close()` DRAIN: they resolve only once every queued event
+ *   has been sent, including events that arrived while a batch was in
+ *   flight (the caller can rely on the tail landing before it reports the
+ *   stage complete). The first send failure flips to text-fallback
+ *   permanently for this execution: the failed batch AND everything still
+ *   queued convert to text via `onTextFallback`, and later events are left
+ *   to the daemon's `onLog` path (`isStructured()` goes false).
+ * @example const sender = createStructuredEventSender({ client, taskId: 't', projectId: 'p', executionId: 'e', epoch: 1, onTextFallback: () => {} })
+ * @param {Object} opts - Options.
+ * @param {Object} opts.client - Runner backend client with `logEvents`.
+ * @param {string} opts.taskId - Task id.
+ * @param {string} opts.projectId - Project id.
+ * @param {string} opts.executionId - Lease execution id.
+ * @param {number} opts.epoch - Lease epoch.
+ * @param {Function} [opts.onTextFallback] - Called with legacy text per convertible event after the fallback flip.
+ * @param {Object} [opts.logger] - Logger for send warnings.
+ * @param {number} [opts.batchSize=25] - Events per batch.
+ * @param {number} [opts.flushMs=500] - Quiet-ms before a partial batch ships.
+ * @returns {Object} Sender with `queueEvent`, `flush`, `close`, `isStructured`.
+ ***/
+export const createStructuredEventSender = ({
+	client,
+	taskId,
+	projectId,
+	executionId,
+	epoch,
+	onTextFallback = () => {},
+	logger = null,
+	batchSize = 25,
+	flushMs = 500,
+}) => {
+	let seq = 0;
+	let pending = [];
+	let structured = true;
+	let timer = null;
+	let inFlight = null;
+
+	const warn = (message) => {
+		try {
+			if (logger && typeof logger.warn === "function") logger.warn(message);
+		} catch {
+			// Logging must never break the run.
+		}
+	};
+
+	const clearTimer = () => {
+		if (timer) {
+			clearTimeout(timer);
+			timer = null;
+		}
+	};
+
+	const armTimer = () => {
+		if (timer || flushMs <= 0) return;
+		timer = setTimeout(() => {
+			timer = null;
+			flush().catch(() => {});
+		}, flushMs);
+		if (typeof timer.unref === "function") timer.unref();
+	};
+
+	const sendBatch = async (batch, batchSeq) => {
+		await client.logEvents({
+			taskId,
+			projectId,
+			executionId,
+			epoch,
+			seq: batchSeq,
+			events: batch,
+		});
+	};
+
+	const fallBack = (failedBatch, err) => {
+		structured = false;
+		clearTimer();
+		// Convert everything not yet sent, not just the failed batch: events
+		// queued while that batch was in flight were never transported
+		// structured and must not vanish during the fallback transition.
+		const unsent = [...failedBatch, ...pending];
+		pending = [];
+		warn(
+			`Structured log transport failed (${err?.message || err}); falling back to text frames.`,
+		);
+		for (const event of unsent) {
+			const text = textForStructuredEvent(event);
+			if (text) {
+				try {
+					onTextFallback(text);
+				} catch {
+					// A throwing fallback must never break the run.
+				}
+			}
+		}
+	};
+
+	const flush = async () => {
+		// Drain loop, not a single pass: events queued while a batch is in
+		// flight must ship too. close() relies on this — the trailing batch
+		// has to be sent before the caller reports the stage complete.
+		// Taking a batch (`pending` → local) is synchronous, so concurrent
+		// flushes can never send the same events twice.
+		for (;;) {
+			if (!structured || pending.length === 0) return;
+			if (inFlight) {
+				await inFlight;
+				continue;
+			}
+			const batch = pending;
+			pending = [];
+			clearTimer();
+			const batchSeq = seq;
+			seq += 1;
+			inFlight = sendBatch(batch, batchSeq).catch((err) => {
+				fallBack(batch, err);
+			});
+			try {
+				await inFlight;
+			} finally {
+				inFlight = null;
+			}
+		}
+	};
+
+	const queueEvent = (event) => {
+		if (!structured) return;
+		const sanitized = sanitizeStructuredEvent(event);
+		if (!sanitized) return;
+		pending.push(sanitized);
+		if (
+			event?.type === "run_finished" ||
+			event?.type === "run_error" ||
+			pending.length >= Math.max(1, batchSize)
+		) {
+			flush().catch(() => {});
+			return;
+		}
+		armTimer();
+	};
+
+	const close = async () => {
+		clearTimer();
+		await flush();
+	};
+
+	const isStructured = () => structured;
+
+	return { queueEvent, flush, close, isStructured };
+};
diff --git a/runner/logEvents.test.js b/runner/logEvents.test.js
new file mode 100644
index 0000000..2c7e7a1
--- /dev/null
+++ b/runner/logEvents.test.js
@@ -0,0 +1,222 @@
+import { describe, it } from "node:test";
+import assert from "node:assert/strict";
+import {
+	createStructuredEventSender,
+	sanitizeStructuredEvent,
+	textForStructuredEvent,
+} from "./logEvents.js";
+
+function stubClient({ failAfter = Infinity } = {}) {
+	const calls = [];
+	let sends = 0;
+	const client = {
+		async logEvents(payload) {
+			sends += 1;
+			calls.push(payload);
+			if (sends > failAfter) {
+				const err = new Error("Backend 404 on /log-events");
+				err.statusCode = 404;
+				throw err;
+			}
+			return { accepted: true, seq: payload.seq };
+		},
+	};
+	return { client, calls };
+}
+
+const ids = { taskId: "t1", projectId: "p1", executionId: "e1", epoch: 1 };
+
+describe("sanitizeStructuredEvent", () => {
+	it("passes clean events through and drops typeless ones", () => {
+		assert.deepEqual(
+			sanitizeStructuredEvent({ type: "assistant_delta", delta: "hi" }),
+			{ type: "assistant_delta", delta: "hi" },
+		);
+		assert.equal(sanitizeStructuredEvent(null), null);
+		assert.equal(sanitizeStructuredEvent({ noType: true }), null);
+	});
+
+	it("redacts secrets before transport", () => {
+		const out = sanitizeStructuredEvent({
+			type: "tool_started",
+			toolName: "bash",
+			args: { apiKey: "supersecretvalue" },
+		});
+		assert.equal(out.args.apiKey, "[REDACTED]");
+		const text = sanitizeStructuredEvent({
+			type: "harness_log",
+			text: "Authorization: Bearer abcdefgh123456",
+		});
+		assert.equal(text.text, "Authorization: Bearer [REDACTED]");
+	});
+
+	it("truncates oversized payloads with a marker instead of dropping", () => {
+		const out = sanitizeStructuredEvent(
+			{ type: "tool_finished", toolName: "bash", result: `ok\n${"x".repeat(2000)}` },
+			1500,
+		);
+		assert.ok(out);
+		assert.match(out.result, /truncated for transport/);
+	});
+
+	it("truncates oversized object-shaped results instead of dropping the event", () => {
+		const out = sanitizeStructuredEvent(
+			{
+				type: "tool_finished",
+				toolName: "bash",
+				result: { content: [{ text: `ok\n${"x".repeat(2000)}` }] },
+			},
+			1500,
+		);
+		assert.ok(out);
+		assert.equal(out.toolName, "bash");
+		assert.match(out.result.content[0].text, /truncated for transport/);
+	});
+});
+
+describe("textForStructuredEvent", () => {
+	it("derives legacy text only for the two pre-structured shapes", () => {
+		assert.equal(
+			textForStructuredEvent({ type: "assistant_delta", delta: "hi" }),
+			"hi",
+		);
+		assert.equal(
+			textForStructuredEvent({ type: "harness_log", text: "hello" }),
+			"hello",
+		);
+		assert.equal(
+			textForStructuredEvent({ type: "tool_started", toolName: "bash" }),
+			null,
+		);
+		assert.equal(textForStructuredEvent(null), null);
+	});
+});
+
+describe("createStructuredEventSender", () => {
+	it("ships sequenced batches on close", async () => {
+		const { client, calls } = stubClient();
+		const sender = createStructuredEventSender({ client, ...ids, flushMs: 0 });
+		sender.queueEvent({ type: "run_started" });
+		sender.queueEvent({ type: "assistant_delta", delta: "hi" });
+		await sender.close();
+		assert.equal(calls.length, 1);
+		assert.equal(calls[0].seq, 0);
+		assert.equal(calls[0].events.length, 2);
+		assert.equal(calls[0].executionId, "e1");
+	});
+
+	it("flushes immediately on run-closing events", async () => {
+		const { client, calls } = stubClient();
+		const sender = createStructuredEventSender({ client, ...ids, flushMs: 60000 });
+		sender.queueEvent({ type: "assistant_delta", delta: "hi" });
+		assert.equal(calls.length, 0);
+		sender.queueEvent({ type: "run_finished" });
+		await sender.flush();
+		assert.equal(calls.length, 1);
+		assert.equal(calls[0].events.length, 2);
+	});
+
+	it("falls back to text on send failure and converts the failed batch", async () => {
+		const { client, calls } = stubClient({ failAfter: 0 });
+		const fallback = [];
+		const sender = createStructuredEventSender({
+			client,
+			...ids,
+			flushMs: 0,
+			onTextFallback: (text) => fallback.push(text),
+		});
+		sender.queueEvent({ type: "assistant_delta", delta: "hello" });
+		sender.queueEvent({ type: "tool_started", toolName: "bash" });
+		await sender.flush();
+		assert.equal(sender.isStructured(), false);
+		// The convertible event in the failed batch reaches the text path;
+		// the tool event has no legacy text form.
+		assert.deepEqual(fallback, ["hello"]);
+		// Later events stay out of the structured path entirely.
+		sender.queueEvent({ type: "assistant_delta", delta: "later" });
+		await sender.flush();
+		assert.equal(calls.length, 1);
+		assert.deepEqual(fallback, ["hello"]);
+	});
+
+	it("redacts secrets in queued batches", async () => {
+		const { client, calls } = stubClient();
+		const sender = createStructuredEventSender({ client, ...ids, flushMs: 0 });
+		sender.queueEvent({
+			type: "tool_started",
+			toolName: "bash",
+			args: { password: "hunter2hunter" },
+		});
+		await sender.close();
+		assert.equal(calls[0].events[0].args.password, "[REDACTED]");
+	});
+
+	it("close() drains events queued while a batch is in flight", async () => {
+		// A controllable client: the first batch stays in flight until we
+		// release it, so the tail event lands in `pending` mid-send.
+		const calls = [];
+		let releaseFirst;
+		const firstGate = new Promise((resolve) => {
+			releaseFirst = resolve;
+		});
+		let sends = 0;
+		const client = {
+			async logEvents(payload) {
+				sends += 1;
+				calls.push(payload);
+				if (sends === 1) await firstGate;
+				return { accepted: true, seq: payload.seq };
+			},
+		};
+		const sender = createStructuredEventSender({
+			client,
+			...ids,
+			batchSize: 2,
+			flushMs: 60000, // timer must not fire during the test
+		});
+		sender.queueEvent({ type: "assistant_delta", delta: "one" });
+		sender.queueEvent({ type: "assistant_delta", delta: "two" }); // batch 0 ships, in flight
+		sender.queueEvent({ type: "run_finished" }); // queued while batch 0 is in flight
+		const closed = sender.close();
+		// close() must not resolve while the tail event is still unsent.
+		let resolvedEarly = false;
+		closed.then(() => {
+			resolvedEarly = true;
+		});
+		await new Promise((r) => setTimeout(r, 25));
+		assert.equal(resolvedEarly, false);
+		assert.equal(calls.length, 1);
+		releaseFirst();
+		await closed;
+		// Both batches shipped before close() resolved, in order.
+		assert.equal(calls.length, 2);
+		assert.deepEqual(
+			calls.map((c) => c.seq),
+			[0, 1],
+		);
+		assert.deepEqual(
+			calls[1].events.map((e) => e.type),
+			["run_finished"],
+		);
+	});
+
+	it("fallback converts events queued during the failed batch too", async () => {
+		const { client } = stubClient({ failAfter: 0 });
+		const fallback = [];
+		const sender = createStructuredEventSender({
+			client,
+			...ids,
+			batchSize: 2,
+			flushMs: 60000,
+			onTextFallback: (text) => fallback.push(text),
+		});
+		sender.queueEvent({ type: "assistant_delta", delta: "one" });
+		sender.queueEvent({ type: "assistant_delta", delta: "two" }); // batch 0 ships and fails
+		sender.queueEvent({ type: "harness_log", text: "three" }); // still pending at failure
+		await sender.flush();
+		assert.equal(sender.isStructured(), false);
+		// Nothing that was queued may vanish during the transition: every
+		// convertible event — failed batch AND pending queue — reaches text.
+		assert.deepEqual(fallback, ["one", "two", "three"]);
+	});
+});
